1	using Arch.Buffer;
2	using Arch.Core;
3	using Arch.Core.Extensions;
4	using OpenSolarMax.Game.Modding;
5	using OpenSolarMax.Game.Modding.Concept;
6	using OpenSolarMax.Game.Modding.ECS;
7	using OpenSolarMax.Mods.Common.Components;
8	using OpenSolarMax.Mods.S2.Concepts;
9	
10	namespace OpenSolarMax.Mods.S2.Systems;
11	
12	/// <summary>
13	/// 沿阵营继承关系树自根向叶传播阵营，维护子实体自身的 InTeam 关系
14	/// </summary>
15	[SimulateSystem, LateUpdate, BothForGameplayAndPreview]
16	[
17	    ReadCurr(typeof(TreeRelationship<InTeam>.AsParent)),
18	    ReadCurr(typeof(TreeRelationship<InTeam>.AsChild)),
19	    ReadCurr(typeof(InTeam.AsAffiliate)),
20	    DelayedCalc
21	]
22	public sealed partial class SynchronizeTeamSystem(World world, IConceptFactory factory)
23	    : IDelayedCalcSystem
24	{
25	    private static readonly QueryDescription _parentsDesc =
26	        new QueryDescription().WithAll<TreeRelationship<InTeam>.AsParent>();
27	
28	    private void SyncToChildren(Entity entity, Entity inheritedTeam, CommandBuffer commandBuffer)
29	    {
30	        // 实体自身的阵营优先，其次继承自父实体
31	        var team =
32	            entity.TryGet<InTeam.AsAffiliate>(out var asAffiliate)
33	            && asAffiliate.Relationship is not null
34	                ? asAffiliate.Relationship.Value.Copy.Team
35	                : inheritedTeam;
36	
37	        if (!entity.TryGet<TreeRelationship<InTeam>.AsParent>(out var asParent))
38	            return;
39	
40	        foreach (var (_, record) in asParent.Relationships)
41	        {
42	            var child = record.Child;
43	            if (!child.IsAlive())
44	                continue;
45	
46	            // 维护子实体的阵营归属（子实体必须带 AsAffiliate 索引组件才能被索引）
47	            if (child.TryGet<InTeam.AsAffiliate>(out var childAffiliate))
48	            {
49	                var current = childAffiliate.Relationship is not null
50	                    ? childAffiliate.Relationship.Value.Copy.Team
51	                    : Entity.Null;
52	
53	                if (current != team)
54	                {
55	                    if (childAffiliate.Relationship is not null)
56	                        commandBuffer.Destroy(childAffiliate.Relationship.Value.Ref);
57	
58	                    if (team != Entity.Null)
59	                        factory.Make(
60	                            world,
61	                            commandBuffer,
62	                            ConceptNames.InTeam,
63	                            new InTeamDescription { Team = team, Affiliate = child }
64	                        );
65	                }
66	            }
67	
68	            // 自根向叶递归，保证多级子实体拿到本帧已更新的队伍
69	            SyncToChildren(child, team, commandBuffer);
70	        }
71	    }
72	
73	    public void Update(CommandBuffer commandBuffer)
74	    {
75	        var query = world.Query(in _parentsDesc);
76	        foreach (var chunk in query.GetChunkIterator())
77	        {
78	            foreach (var idx in chunk)
79	            {
80	                var entity = chunk.Entity(idx);
81	
82	                // 仅从根实体开始；非根实体由其父实体递归处理
83	                if (
84	                    entity.TryGet<TreeRelationship<InTeam>.AsChild>(out var asChild)
85	                    && asChild.Relationship is not null
86	                )
87	                    continue;
88	
89	                SyncToChildren(entity, Entity.Null, commandBuffer);
90	            }
91	        }
92	    }
93	}
```

