23: {
24:     [Query]
25:     [All<ColonizationState, Colonizable, InTeam.AsAffiliate, AnchoredShipsRegistry>]
26:     private static void UpdateColonization(
27:         [Data] GameTime time,
28:         ref ColonizationState state,
29:         in Colonizable colonizable,
30:         in AnchoredShipsRegistry shipsRegistry
31:     )
32:     {
33:         if (shipsRegistry.Ships.Count != 1)
34:         {
35:             state.Event = ColonizationEvent.Idle;
36:             return;
37:         }
38: 
39:         var colonizeTeam = shipsRegistry.Ships.First().Key;
40:         var shipsNum = shipsRegistry.Ships.First().Count();
41: 
42:         var deltaProgress =
43:             shipsNum
44:             * colonizeTeam.Get<ColonizationAbility>().ProgressPerSecond
45:             * (float)time.ElapsedGameTime.TotalSeconds;
46: 
47:         if (state.Team == colonizeTeam || state.Team == Entity.Null)
48:         {
49:             if (state.Progress >= colonizable.Volume)
50:                 state.Event = ColonizationEvent.Idle;
51:             else
52:             {
53:                 state.Team = colonizeTeam;
54:                 state.Progress += deltaProgress;
55: 
56:                 if (state.Progress > colonizable.Volume)
57:                 {
58:                     state.Progress = colonizable.Volume;
59:                     state.Event = ColonizationEvent.Finished;
60:                 }
61:                 else
62:                     state.Event = ColonizationEvent.Progressing;
63:             }
64:         }
65:         else
66:         {
67:             state.Progress -= deltaProgress;
68: 
69:             if (state.Progress < 0)
70:             {
71:                 state.Progress = -state.Progress;
72:                 state.Team = colonizeTeam;
73:                 state.Event = ColonizationEvent.Destroyed;
74:             }
75:             else
76:                 state.Event = ColonizationEvent.Destroying;
77:         }
78:     }
