11: internal sealed class WorldLoader(IConceptFactory factory, ITranslatorRegistry translators)
12: {
13:     public IEnumerator LoadStepByStep(LevelFile level, World world, CommandBuffer commandBuffer)
14:     {
15:         // 所有经过仿真系统后处理过至少一次的实体的代号
16:         var satisfiedEntities = new HashSet<string>();
17:         // 所有有名实体
18:         var namedEntities = new Dictionary<string, Entity>();
19:         // 所有有名配置
20:         var namedDeclarations = new Dictionary<string, IDeclaration>();
21: 
22:         // 首先解析所有模板
23:         foreach (var (id, templateStatement) in level.Templates)
24:         {
25:             var configuration = templateStatement
26:                 .BaseDecalarationIds.Select(k => namedDeclarations[k])
27:                 .Append(templateStatement.Declaration)
28:                 .Aggregate((c1, c2) => c1.Aggregate(c2));
29:             namedDeclarations.Add(id, configuration);
30:         }
31: 
32:         // 解析所有实体
33:         foreach (var (optionalId, entityStatement) in level.Entities)
34:         {
35:             // 如果没有对应的描述翻译器, 则跳过该实体
36:             // TODO: 应当应用更严格的检查
37:             if (
38:                 !translators.TryGetBySchema(
39:                     entityStatement.SchemaName,
40:                     out var conceptName,
41:                     out var translator
42:                 )
43:             )
44:                 continue;
45: 
46:             var configuration = entityStatement
47:                 .BaseDecalarationIds.Select(k => namedDeclarations[k])
48:                 .Append(entityStatement.Declaration)
49:                 .Aggregate((c1, c2) => c1.Aggregate(c2));
50: 
51:             // 检查是否所有依赖均已满足
52:             if (configuration.Requirements.Any(s => !satisfiedEntities.Contains(s)))
53:             {
54:                 // 有依赖的实体未初始化过，需要交给外部计算一帧
55:                 yield return null;
56:                 Debug.Assert(namedEntities.Values.All(e => e.GetComponentTypes().Count > 0));
57:                 satisfiedEntities.UnionWith(namedEntities.Keys);
58:             }
59: 
60:             // 生成描述对象
61:             var description = translator.ToDescription(configuration, namedEntities);
62: 
63:             // 构造实体
64:             var entity = factory.Make(world, commandBuffer, conceptName, description);
65: 
66:             // 记录实体
67:             if (optionalId is not null)
68:                 namedEntities[optionalId] = entity;
69:         }
70: 
71:         yield return null;
72:     }
