11: /// <param name="declarationSchemaInfos">从配置模式名称到配置模式类型的映射</param>
12: internal class DeclarationStatementJsonConverter(
13:     IReadOnlyDictionary<string, string> schemaNamesByDeclarationId,
14:     IReadOnlyDictionary<string, DeclarationSchemaInfo> declarationSchemaInfos
15: ) : JsonConverter<DeclarationStatement>
16: {
17:     public override DeclarationStatement? Read(
18:         ref Utf8JsonReader reader,
19:         Type typeToConvert,
20:         JsonSerializerOptions options
21:     )
22:     {
23:         var element = JsonElement.ParseValue(ref reader);
24: 
25:         var baseProp = element.GetProperty("$base");
26:         var baseDeclarationIds = baseProp.ValueKind switch
27:         {
28:             JsonValueKind.String => [baseProp.GetString()!],
29:             JsonValueKind.Array => baseProp.EnumerateArray().Select(x => x.GetString()!).ToArray(),
30:             _ => throw new JsonException(),
31:         };
32: 
33:         var schemaName = schemaNamesByDeclarationId[baseDeclarationIds[0]];
34:         if (baseDeclarationIds.Any(b => schemaNamesByDeclarationId[b] != schemaName))
35:             throw new Exception("All base configuration should have the same configuration key");
36: 
37:         var configuration = (IDeclaration)
38:             element.Deserialize(declarationSchemaInfos[schemaName].Type, options)!;
39: 
40:         return new DeclarationStatement(
41:             schemaName,
42:             [.. baseDeclarationIds.Where(b => b != schemaName)],
43:             configuration
44:         );
45:     }
