31:         Entity entity,
32:         in InTeam.AsAffiliate asAffiliate,
33:         in JumpingStatus jumpingStatus,
34:         in AbsoluteTransform shipPose,
35:         [Data] in AbsoluteTransform planetPose,
36:         [Data] in float range,
37:         [Data] in Registry<Entity, (Entity Ship, float Distance)> result
38:     )
39:     {
40:         if (jumpingStatus.State == JumpingState.Idle)
41:             return;
42: 
43:         // 矩形判断，减少计算量
44:         var diffX = shipPose.Translation.X - planetPose.Translation.X;
45:         var diffY = shipPose.Translation.Y - planetPose.Translation.Y;
46:         if (diffX > range || diffX < -range || diffY > range || diffY < -range)
47:             return;
48: 
49:         // 距离判断
50:         var distance = MathF.Sqrt(diffX * diffX + diffY * diffY);
51:         if (distance > range)
52:             return;
53: 
54:         Debug.Assert(asAffiliate.Relationship is not null);
55:         result[asAffiliate.Relationship.Value.Copy.Team].Add((entity, distance));
56:     }
