51: /// <summary>
52: /// 系统执行顺序图：系统类型清单与带来源标签的顺序边，经 BuildFrom 生成。
53: /// </summary>
54: /// <param name="Systems">图中的所有系统类型</param>
55: /// <param name="Orders">图中的所有顺序边（OrderedTypePair.Before 先于 After 执行）及其来源与组件标签</param>
56: internal sealed record SystemGraph(
57:     ImmutableArray<Type> Systems,
58:     ImmutableDictionary<OrderedTypePair, ImmutableHashSet<EdgeLabel>> Orders
59: )
60: {
61:     private static void ValidateExplicitOrdersSelfConsistency(
62:         IReadOnlyCollection<SystemDeclaration> declarations
63:     )
64:     {
65:         var systems = declarations.Select(d => d.SystemType).ToHashSet();
66:         var fineWithUnorderedPairs = declarations
67:             .SelectMany(d => d.FineWithPairs)
68:             .Where(f => systems.Contains(f.Sys1) && systems.Contains(f.Sys2))
69:             .Select(f => new UnorderedTypePair(f.Sys1, f.Sys2))
70:             .ToHashSet();
71:         var explicitUnorderedPairs = declarations
72:             .SelectMany(d => d.ExplicitOrders)
73:             .Where(o => systems.Contains(o.Before) && systems.Contains(o.After))
74:             .ToLookup(o => new UnorderedTypePair(o.Before, o.After));
75:         foreach (var group in explicitUnorderedPairs)
76:         {
77:             if (group.Count() > 1 || fineWithUnorderedPairs.Contains(group.Key))
78:                 throw new Exception(
79:                     $"Conflicted explicit execution order between {group.Key.Sys1} and {group.Key.Sys2}"
80:                 );
81:         }
82:     }
83: 
84:     private static (
85:         HashSet<(OrderedTypePair, Type)> ReadWriteOrders,
86:         HashSet<(UnorderedTypePair, Type)> WriterConflicts // TODO: 考虑用 AccessPhase 为键的映射
87:     ) ExtractReadWriteOrdersAndConflicts(IReadOnlyCollection<SystemDeclaration> declarations)
88:     {
89:         // 记录合法的读写顺序边
90:         var readWriteOrders = new HashSet<(OrderedTypePair, Type)>();
91: 
92:         // 记录双写的冲突边。这些冲突边每个都需要被后续显式顺序声明覆盖才行
93:         var writerConflicts = new HashSet<(UnorderedTypePair, Type)>();
94: 
95:         // 获取所有涉及到的组件类型（不含通配符）
96:         var allComponents = declarations
97:             .SelectMany(d => d.Accesses.Keys)
98:             .Where(c => c != typeof(AllComponents))
99:             .ToHashSet();
100: 
101:         // 逐个组件类型处理
102:         foreach (var componentType in allComponents)
103:         {
104:             // 访问该组件的所有系统，按照访问的阶段分为三部分
105:             var buckets = new HashSet<Type>[] { [], [], [] }; // TODO: 考虑复用
106:             foreach (var decl in declarations)
107:             {
108:                 if (
109:                     decl.Accesses.TryGetValue(componentType, out var access)
110:                     || decl.Accesses.TryGetValue(typeof(AllComponents), out access)
111:                 )
112:                     // 如果声明中包含该组件（AllComponents 也算），则记录进入对应访问阶段中
113:                     buckets[(int)access.Phase].Add(decl.SystemType);
114:             }
115: 
116:             // 为同一组件不同阶段的访问者两两创建顺序读写边
117:             for (var before = 0; before < 3; before++)
118:             for (var after = before + 1; after < 3; after++)
119:             {
120:                 foreach (var sys1 in buckets[before])
121:                 foreach (var sys2 in buckets[after])
122:                 {
123:                     if (sys1 == sys2)
124:                         continue; // 相同系统间不建立边
125:                     readWriteOrders.Add((new OrderedTypePair(sys1, sys2), componentType));
126:                 }
127:             }
128: 
129:             // 记录同一访问阶段内冲突的边
130:             static void AddConflicts(
131:                 HashSet<(UnorderedTypePair, Type)> conflicts,
132:                 Type componentType,
133:                 HashSet<Type> bucket
134:             )
135:             {
136:                 if (bucket.Count < 2)
137:                     return;
138:                 var set = bucket.ToList();
139:                 for (var i = 0; i < set.Count; i++)
140:                 for (var j = i + 1; j < set.Count; j++)
141:                     conflicts.Add((new UnorderedTypePair(set[i], set[j]), componentType));
142:             }
143:             AddConflicts(writerConflicts, componentType, buckets[(int)AccessPhase.Write]);
144:         }
145: 
146:         return (readWriteOrders, writerConflicts);
147:     }
148: 
149:     private static HashSet<(OrderedTypePair, Type)> ExtractExplicitOrders(
150:         IReadOnlyCollection<SystemDeclaration> declarations
151:     )
152:     {
153:         var systems = declarations.Select(d => d.SystemType).ToHashSet();
154:         return declarations
155:             .SelectMany(d => d.ExplicitOrders)
156:             .Where(o => systems.Contains(o.Before) && systems.Contains(o.After))
157:             .SelectMany(o => o.Components.Select(c => (new OrderedTypePair(o.Before, o.After), c)))
158:             .ToHashSet();
159:     }
160: 
161:     private static HashSet<(UnorderedTypePair, Type)> ExtractFineWithPairs(
162:         IReadOnlyCollection<SystemDeclaration> declarations
163:     )
164:     {
165:         var systems = declarations.Select(d => d.SystemType).ToHashSet();
166:         return declarations
167:             .SelectMany(d => d.FineWithPairs)
168:             .Where(p => systems.Contains(p.Sys1) && systems.Contains(p.Sys2))
169:             .SelectMany(p => p.Components.Select(c => (new UnorderedTypePair(p.Sys1, p.Sys2), c)))
170:             .ToHashSet();
171:     }
172: 
173:     private static HashSet<OrderedTypePair> ExtractPriorityOrders(
174:         IReadOnlyCollection<SystemDeclaration> declarations
175:     )
176:     {
177:         var systems = declarations.Select(d => d.SystemType).ToHashSet();
178: 
179:         // 先按优先级分组
180:         var priorityGroups = declarations
181:             .Where(d => d.Priority.HasValue)
182:             .GroupBy(d => d.Priority!.Value, d => d.SystemType)
183:             .ToImmutableSortedDictionary(g => g.Key, g => g.ToHashSet());
184: 
185:         // 再两两创建边
186:         var priorityOrders = new HashSet<OrderedTypePair>();
187:         foreach (var (priority1, group1) in priorityGroups)
188:         foreach (var (priority2, group2) in priorityGroups.SkipWhile(p => p.Key <= priority1))
189:         foreach (var sys1 in group1)
190:         foreach (var sys2 in group2)
191:             priorityOrders.Add(new OrderedTypePair(sys1, sys2));
192: 
193:         return priorityOrders;
194:     }
195: 
196:     private static bool CancelOutConflictsByExplicitOrders(
197:         HashSet<(UnorderedTypePair, Type)> writerConflicts,
198:         IReadOnlySet<(OrderedTypePair, Type)> explicitOrders,
199:         List<string> errors
200:     )
201:     {
202:         bool pass = true;
203:         foreach (var (order, type) in explicitOrders)
204:         {
205:             // 是否抵消了冲突？
206:             if (writerConflicts.Remove((order.Unorder(), type)))
207:                 continue;
208: 
209:             // 如果没有抵消冲突，说明不必要
210:             errors.Add(
211:                 $"Explicit order between {order.Before.Name} and {order.After.Name} on component {type.Name} "
212:                     + "is invalid: an order declaration requires both systems to write the component, "
213:                     + "but at least one of them does not"
214:             );
215: 
216:             // 总之校验失败
217:             pass = false;
218:         }
219: 
220:         return pass;
221:     }
222: 
223:     private static bool CancelOutConflictsByFineWithPairs(
224:         HashSet<(UnorderedTypePair, Type)> writerConflicts,
225:         IReadOnlySet<(UnorderedTypePair, Type)> fineWithPairs,
226:         List<string> errors
227:     )
228:     {
229:         bool pass = true;
230:         foreach (var (pair, type) in fineWithPairs)
231:         {
232:             // 是否抵消了冲突？
233:             if (writerConflicts.Remove((pair, type)))
234:                 continue;
235: 
236:             // 如果没有抵消冲突，说明不必要
237:             errors.Add(
238:                 $"FineWith declaration between {pair.Sys1.Name} and {pair.Sys2.Name} on component {type.Name} "
239:                     + "is invalid: an order declaration requires both systems to write the component, "
240:                     + "but at least one of them does not"
241:             );
242: 
243:             // 总之校验失败
244:             pass = false;
245:         }
246: 
247:         return pass;
248:     }
249: 
250:     private static void CancelOutConflictsByPriorityOrders(
251:         HashSet<(OrderedTypePair, Type)> readWriteOrders,
252:         HashSet<(UnorderedTypePair, Type)> writerConflicts,
253:         IReadOnlySet<OrderedTypePair> priorityOrders
254:     )
255:     {
256:         foreach (var order in priorityOrders)
257:         {
258:             writerConflicts.RemoveWhere(p => p.Item1 == order.Unorder());
259:             readWriteOrders.RemoveWhere(p => p.Item1 == order);
260:         }
261:     }
262: 
263:     private static bool ValidateReadWriteConflicts(
264:         IReadOnlySet<(UnorderedTypePair, Type)> writerConflicts,
265:         List<string> errors
266:     )
267:     {
268:         bool pass = true;
269: 
270:         foreach (var (pair, type) in writerConflicts)
271:         {
272:             errors.Add(
273:                 "Multiple writers of one component must explicitly declare pairwise order! "
274:                     + $"Component {type.Name} between {pair.Sys1.Name} and {pair.Sys2.Name} "
275:                     + "requires an order declaration listing this component."
276:             );
277:             pass = false;
278:         }
279: 
280:         return pass;
281:     }
282: 
283:     /// <summary>
284:     /// 从同一 SystemStage 的声明集合构建执行顺序图，声明间的矛盾与冲突一次性报出。
285:     /// </summary>
286:     public static SystemGraph BuildFrom(IReadOnlyCollection<SystemDeclaration> declarations)
287:     {
288:         var errors = new List<string>();
289: 
290:         // 只考虑两侧系统都在本次输入中的声明；对位于输入外的系统的声明静默跳过。
291:         // TODO: 这是为了解决预览时与游玩时系统共享的问题，需要探讨有无更严格方案。
292: 
293:         // 同一对系统不得同时有 FineWith 和 ExecuteAfter/Before
294:         ValidateExplicitOrdersSelfConsistency(declarations);
295: 
296:         // 提取读写边与双写冲突
297:         var (readWriteOrders, writerConflicts) = ExtractReadWriteOrdersAndConflicts(declarations);
298: 
299:         // 提取显式顺序边、FineWith 对、优先级边
300:         var explicitOrders = ExtractExplicitOrders(declarations);
301:         var fineWithPairs = ExtractFineWithPairs(declarations);
302:         var priorityOrders = ExtractPriorityOrders(declarations);
303: 
304:         // 消除冲突
305:         CancelOutConflictsByExplicitOrders(writerConflicts, explicitOrders, errors);
306:         CancelOutConflictsByFineWithPairs(writerConflicts, fineWithPairs, errors);
307:         CancelOutConflictsByPriorityOrders(readWriteOrders, writerConflicts, priorityOrders);
308: 
309:         // 校验仍未抵消的多写冲突
310:         ValidateReadWriteConflicts(writerConflicts, errors);
311: 
312:         // 批量报错
313:         if (errors.Count > 0)
314:         {
315:             throw new Exception(
316:                 "Invalid execution order declarations found:\n" + string.Join("\n", errors)
317:             );
318:         }
319:         Debug.Assert(writerConflicts.Count == 0);
320: 
321:         // 组装所有边
322:         var readWriteEdges = readWriteOrders.Select(p =>
323:             (p.Item1, new EdgeLabel(EdgeSource.ReadWrite, p.Item2))
324:         );
325:         var explicitEdges = explicitOrders.Select(p =>
326:             (p.Item1, new EdgeLabel(EdgeSource.Explicit, p.Item2))
327:         );
328:         var priorityEdges = priorityOrders.Select(o =>
329:             (o, new EdgeLabel(EdgeSource.Priority, null))
330:         );
331:         var edges = readWriteEdges
332:             .Concat(explicitEdges)
333:             .Concat(priorityEdges)
334:             .GroupBy(p => p.Item1, p => p.Item2)
335:             .ToImmutableDictionary(g => g.Key, g => g.ToImmutableHashSet());
336: 
337:         return new([.. declarations.Select(d => d.SystemType)], edges);
338:     }
339: 
340:     /// <summary>
341:     /// 按边约束拓扑排序图中的系统，存在环时抛异常。
342:     /// </summary>
343:     public ImmutableArray<Type> TopologicalSort()
344:     {
345:         var ordersLookup = Orders.Keys.ToLookup(p => p.After, p => p.Before);
346:         var graph = Systems.ToDictionary(t => t, t => ordersLookup[t].ToHashSet());
347: 
348:         var systems = new List<Type>();
349:         while (graph.Count > 0)
350:         {
351:             var okSystemTypes = graph
352:                 .Where(pair => pair.Value.Count == 0)
353:                 .Select(pair => pair.Key)
354:                 .ToList();
355: 
356:             if (okSystemTypes.Count == 0)
357:                 throw new ArgumentException("Cyclic connections are not allowed");
358: 
359:             foreach (var okSystemType in okSystemTypes)
360:             {
361:                 graph.Remove(okSystemType);
362:                 foreach (var (_, dependencies) in graph)
363:                     dependencies.Remove(okSystemType);
364:             }
365: 
366:             systems.AddRange(okSystemTypes);
367:         }
368: 
369:         return [.. systems];
370:     }
371: }

