63:     /// <summary>
64:     /// 把 LateUpdate 图按声明拆分为 LateUpdate1（延迟操作系统及其上游）与 LateUpdate2（其余）。
65:     /// </summary>
66:     private static (SystemGraph LateUpdate1, SystemGraph LateUpdate2) SplitLateUpdate(
67:         SystemGraph graph,
68:         IReadOnlyCollection<SystemDeclaration> lateUpdateDeclarations
69:     )
70:     {
71:         // 种子集 = 声明 [DelayedCalc] 的系统，即会发生延迟操作、必然参与不动点迭代的系统
72:         var seedSystems = lateUpdateDeclarations
73:             .Where(d => d.DelayedCalc)
74:             .Select(d => d.SystemType)
75:             .ToHashSet();
76: 
77:         // 构建反向邻接表：After -> Before
78:         var upstreamMap = graph.Orders.ToLookup(kv => kv.Key.After, kv => kv.Key.Before);
79: 
80:         // 从种子集出发反向 BFS，收集所有上游（直接 + 间接）。
81:         // 上游的输出是延迟操作的输入，因而被拖入不动点迭代，须与种子一同反复执行
82:         var upstreamClosure = new HashSet<Type>();
83:         var queue = new Queue<Type>(seedSystems);
84:         while (queue.Count > 0)
85:         {
86:             var current = queue.Dequeue();
87:             foreach (var upstream in upstreamMap[current])
88:             {
89:                 if (upstreamClosure.Add(upstream))
90:                     queue.Enqueue(upstream);
91:             }
92:         }
93: 
94:         // LateUpdate1 = 种子 ∪ 其上游（参与不动点迭代的系统）；
95:         // 其余系统的输出不进入环路，在不动点循环收敛后归入 LateUpdate2 执行
96:         var lateUpdate1Systems = new HashSet<Type>(upstreamClosure);
97:         lateUpdate1Systems.UnionWith(seedSystems);
98:         var lateUpdate2Systems = new HashSet<Type>(graph.Systems);
99:         lateUpdate2Systems.ExceptWith(lateUpdate1Systems);
100: 
101:         return (FilterGraph(graph, lateUpdate1Systems), FilterGraph(graph, lateUpdate2Systems));
102:     }
103: 
104:     /// <summary>
105:     /// 从图中提取仅含指定成员间边的子图。
106:     /// </summary>
107:     private static SystemGraph FilterGraph(SystemGraph graph, IReadOnlySet<Type> members)
108:     {
109:         var filteredOrders = graph
110:             .Orders.Where(kv => members.Contains(kv.Key.Before) && members.Contains(kv.Key.After))
111:             .ToImmutableDictionary();
112: 
113:         return new([.. members], filteredOrders);
114:     }
115: }

