30:     private static void CollectJsonLevels(
31:         IFileSystem fs,
32:         UPath path,
33:         HashSet<UPath> visited,
34:         List<(UPath Path, JsonLevel Level)> collected
35:     )
36:     {
37:         // 必须在处理 includes 之前登记，防止循环引用导致无限递归
38:         if (!visited.Add(path))
39:             return;
40: 
41:         using var stream = fs.OpenFile(path, FileMode.Open, FileAccess.Read);
42: 
43:         var basicSerializerOptions = new JsonSerializerOptions()
44:         {
45:             PropertyNameCaseInsensitive = true,
46:             IncludeFields = true,
47:         };
48:         var jsonLevel =
49:             JsonSerializer.Deserialize<JsonLevel>(stream, basicSerializerOptions)
50:             ?? throw new JsonException();
51: 
52:         // 先处理被包含的文件，使其模板和实体位于当前文件内容之前
53:         foreach (var includePath in jsonLevel.Includes)
54:         {
55:             CollectJsonLevels(
56:                 fs,
57:                 UPath.Combine(path.GetDirectory(), includePath),
58:                 visited,
59:                 collected
60:             );
61:         }
62: 
63:         collected.Add((path, jsonLevel));
64:     }
65: 
66:     private LevelFile ParseAndMerge(List<(UPath Path, JsonLevel Level)> collected)
67:     {
68:         // 初始化从配置模式索引到配置模式名称的映射
69:         var schemaNamesByDeclarationId = declarationSchemaInfos.Keys.ToDictionary(key => key);
70: 
71:         var statementSerializerOptions = new JsonSerializerOptions()
72:         {
73:             PropertyNameCaseInsensitive = true,
74:             IncludeFields = true,
75:         };
76:         // 添加基础类型转换器
77:         statementSerializerOptions.Converters.Add(new JsonStringEnumConverter());
78:         statementSerializerOptions.Converters.Add(new Vector2JsonConverter());
79:         statementSerializerOptions.Converters.Add(new ColorJsonConverter());
80:         statementSerializerOptions.Converters.Add(new BlendStateJsonConverter());
81:         // 添加 OneOf 转换器
82:         statementSerializerOptions.Converters.Add(new OneOfJsonConverterFactory());
83:         // 添加语句转换器
84:         statementSerializerOptions.Converters.Add(
85:             new DeclarationStatementJsonConverter(
86:                 schemaNamesByDeclarationId,
87:                 declarationSchemaInfos
88:             )
89:         );
90: 
91:         var templates = new Dictionary<string, DeclarationStatement>();
92:         var entities = new List<(string? Id, DeclarationStatement Statement)>();
93:         var configBuilder = new ConfigurationBuilder();
94: 
95:         foreach (var (path, jsonLevel) in collected)
96:         {
97:             // 解析模板语句
98:             foreach (var (templateKey, templateJsonElement) in jsonLevel.Templates)
99:             {
100:                 if (templates.ContainsKey(templateKey))
101:                     throw new Exception($"模板 \"{templateKey}\" 重复定义（文件：{path}）");
102: 
103:                 var statement = templateJsonElement.Deserialize<DeclarationStatement>(
104:                     statementSerializerOptions
105:                 )!;
106: 
107:                 // 构造并添加新的模板语句
108:                 templates.Add(templateKey, statement);
109: 
110:                 // 将该模板语句的配置类型加入到缓存中
111:                 schemaNamesByDeclarationId[templateKey] = statement.SchemaName;
112:             }
113: 
114:             // 解析实体语句
115:             foreach (var entityJsonElement in jsonLevel.Entities)
116:             {
117:                 var statement = entityJsonElement.Deserialize<DeclarationStatement>(
118:                     statementSerializerOptions
119:                 )!;
120: 
121:                 // 获取id, 如果有的话
122:                 var id = entityJsonElement.TryGetProperty("$id", out var idProp)
123:                     ? idProp.GetString()
124:                     : null;
125: 
126:                 // 构造并添加新的实体语句
127:                 entities.Add((id, statement));
128:             }
129: 
130:             // 将该文件的配置转换为 IConfiguration 后叠加
131:             if (jsonLevel.Configs is { } configs)
132:             {
133:                 using var configStream = new MemoryStream(
134:                     System.Text.Encoding.UTF8.GetBytes(configs.GetRawText())
135:                 );
136:                 configBuilder.AddConfiguration(
137:                     new ConfigurationBuilder().AddJsonStream(configStream).Build()
138:                 );
139:             }
140:         }
141: 
142:         return new LevelFile
143:         {
144:             Templates = templates,
145:             Entities = entities,
146:             Configs = configBuilder.Sources.Count > 0 ? configBuilder.Build() : null,
147:         };
148:     }
149: 
150:     public LevelFile Load(IFileSystem fs, IAssetsManager assets, in UPath path)
151:     {
152:         // 收集阶段：只加载文件骨架，得到"被包含文件在前"的有序序列
153:         var collected = new List<(UPath Path, JsonLevel Level)>();
154:         var visited = new HashSet<UPath>(); // 记录已经加载过的文件，避免重复加载和循环引用
155:         CollectJsonLevels(fs, path, visited, collected);
156: 
157:         // 解析阶段：按序解析各文件的模板、实体与配置，并合并到最终结果
158:         return ParseAndMerge(collected);
159:     }
160: }

