8: public record ConceptInfo
9: {
10:     public string Name { get; }
11: 
12:     public ImmutableArray<Type> DefinitionTypes { get; }
13: 
14:     public Type? DescriptionType { get; }
15: 
16:     public ImmutableArray<Type> ApplierTypes { get; }
17: 
18:     private ConceptInfo(
19:         string name,
20:         IReadOnlyList<Type> definitionTypes,
21:         Type? descriptionType,
22:         IReadOnlyList<Type> applierTypes
23:     )
24:     {
25:         Name = name;
26:         DefinitionTypes = [.. definitionTypes];
27:         DescriptionType = descriptionType;
28:         ApplierTypes = [.. applierTypes];
29:     }
30: 
31:     public static ConceptInfo Define(
32:         string name,
33:         Type definitionType,
34:         Type? descriptionType,
35:         Type? applierType
36:     )
37:     {
38:         var expectedApplierInterface = descriptionType is null
39:             ? typeof(IApplier)
40:             : typeof(IApplier<>).MakeGenericType(descriptionType);
41:         if (
42:             applierType is not null
43:             && !applierType.GetInterfaces().Contains(expectedApplierInterface)
44:         )
45:             throw new Exception("the applier type must support the corresponding definition type!");
46: 
47:         return new ConceptInfo(
48:             name,
49:             [definitionType],
50:             descriptionType,
51:             applierType is null ? [] : [applierType]
52:         );
53:     }
54: 
55:     public ConceptInfo Extend(Type? definitionType, Type? applierType)
56:     {
57:         var expectedApplierInterface = DescriptionType is null
58:             ? typeof(IApplier)
59:             : typeof(IApplier<>).MakeGenericType(DescriptionType);
60:         if (
61:             applierType is not null
62:             && !applierType.GetInterfaces().Contains(expectedApplierInterface)
63:         )
64:             throw new Exception("the applier type must support the corresponding definition type!");
65: 
66:         return new ConceptInfo(
67:             Name,
68:             definitionType is null ? DefinitionTypes : [.. DefinitionTypes, definitionType],
69:             DescriptionType,
70:             applierType is null ? ApplierTypes : [.. ApplierTypes, applierType]
71:         );
72:     }
73: }

