7: public static class PluginFactory
8: {
9:     /// <summary>
10:     /// 根据给定参数和选项，反射地创建指定插件类型
11:     /// </summary>
12:     /// <param name="pluginType">待实例化的插件的类型</param>
13:     /// <param name="fixedArguments">插件构造函数中固定的、必需的参数</param>
14:     /// <param name="dynamicArguments">插件构造函数中动态的、可选的参数</param>
15:     /// <returns></returns>
16:     public static object Instantiate(
17:         Type pluginType,
18:         IReadOnlyList<(Type Type, object Value)> fixedArguments,
19:         IReadOnlyDictionary<Type, object> dynamicArguments
20:     )
21:     {
22:         var constructorInfos = pluginType.GetConstructors(
23:             BindingFlags.Public | BindingFlags.Instance
24:         );
25:         if (constructorInfos.Length > 1)
26:             throw new Exception($"{pluginType} has more than one public constructors!");
27:         if (constructorInfos.Length == 0)
28:             throw new Exception($"{pluginType} has no public constructor!");
29:         var constructor = constructorInfos[0];
30:         var parameterInfos = constructor.GetParameters();
31: 
32:         var arguments = new object[parameterInfos.Length];
33:         var i = 0;
34: 
35:         // 填写固定参数
36:         if (parameterInfos.Length < fixedArguments.Count)
37:             throw new Exception(
38:                 $"{pluginType}'s constructor lacks sufficient parameters for its fixed arguments"
39:             );
40:         for (; i < fixedArguments.Count; i++)
41:         {
42:             if (parameterInfos[i].ParameterType != fixedArguments[i].Type)
43:                 throw new Exception(
44:                     $"{pluginType}'s constructor's parameters does not match its fixed arguments"
45:                 );
46:             arguments[i] = fixedArguments[i].Value;
47:         }
48: 
49:         // 填写动态参数
50:         for (; i < parameterInfos.Length; i++)
51:         {
52:             if (parameterInfos[i].ParameterType == typeof(IConfiguration))
53:             {
54:                 // 特殊处理 IConfiguration
55:                 if (
56:                     parameterInfos[i].GetCustomAttribute<SectionAttribute>()
57:                     is not { } sectionAttribute
58:                 )
59:                     throw new Exception(
60:                         "IConfiguration parameter must be declared with a Section attribute"
61:                     );
62:                 var configurationRoot = (IConfigurationRoot)
63:                     dynamicArguments[typeof(IConfigurationRoot)];
64:                 var configurationAggregator = new ConfigurationBuilder();
65:                 foreach (var section in sectionAttribute.Section)
66:                     configurationAggregator.AddConfiguration(configurationRoot.GetSection(section));
67:                 arguments[i] = configurationAggregator.Build();
68:             }
69:             else
70:                 arguments[i] = dynamicArguments[parameterInfos[i].ParameterType];
71:         }
72: 
73:         return constructor.Invoke(arguments);
74:     }
75: }

