    private static bool InRange(in AbsoluteTransform center, float radius, in AbsoluteTransform target)
    {
        var diffX = target.Translation.X - center.Translation.X;
        var diffY = target.Translation.Y - center.Translation.Y;
        return diffX * diffX + diffY * diffY <= radius * radius;
    }

    [Query]
    [All<Colonizable, InTeam.AsAffiliate, AbsoluteTransform>]
    private void ConvertCelestialBody(
        Entity celestialBody,
        in Colonizable colonizable,
        in InTeam.AsAffiliate asAffiliate,
        in AbsoluteTransform pose,
        [Data] in AbsoluteTransform center,
        [Data] in float radius,
        [Data] Entity conversionTeam,
        [Data] CommandBuffer commandBuffer
    )
    {
        if (!InRange(in center, radius, in pose))
            return;

        if (asAffiliate.Relationship?.Copy.Team == conversionTeam)
            return;

        if (asAffiliate.Relationship is not null)
            commandBuffer.Destroy(asAffiliate.Relationship.Value.Ref);

        factory.Make(
            world,
            commandBuffer,
            new InTeamDescription { Team = conversionTeam, Affiliate = celestialBody }
        );

        commandBuffer.Set(
            celestialBody,
            new ColonizationState
            {
                Team = conversionTeam,
                Progress = colonizable.Volume,
                Event = ColonizationEvent.Idle,
            }
        );
    }

    [Query]
    [All<PopulationCost, InTeam.AsAffiliate, AbsoluteTransform>]
    private void ConvertShip(... same but no colonization state ...)

    [Query]
    [All<Camera, AbsoluteTransform>]
    private static void MeasureLevelBound(
        in Camera camera, in AbsoluteTransform viewPose, [Data] in Vector3 center, [Data] ref float bound)
    { ... }

    [Query]
    [All<ConversionWaveState, AbsoluteTransform>]
    private void Settle(
        Entity wave,
        in ConversionWaveState state,
        in AbsoluteTransform pose,
        [Data] CommandBuffer commandBuffer
    )
    {
        ConvertCelestialBodyQuery(world, in pose, in state.Radius, state.ConversionTeam, commandBuffer);
        ConvertShipQuery(world, in pose, in state.Radius, state.ConversionTeam, commandBuffer);

        var bound = 0f;
        MeasureLevelBoundQuery(world, in pose.Translation, ref bound);
        if (bound > 0 && state.Radius > bound)
            commandBuffer.Destroy(wave);
    }

    public void Update(CommandBuffer commandBuffer) => SettleQuery(world, commandBuffer);
}
