```csharp
[Query]
[All<Camera, AbsoluteTransform>]
private static void MeasureLevelBound(
    in Camera camera,
    in AbsoluteTransform viewPose,
    [Data] in Vector3 center,
    [Data] ref float bound
)
{
    var halfWidth = camera.Width * 0.5f;
    var halfHeight = camera.Height * 0.5f;

    for (var i = 0; i < 4; i++)
    {
        var cornerX = viewPose.Translation.X + ((i & 1) == 0 ? -halfWidth : halfWidth);
        var cornerY = viewPose.Translation.Y + ((i & 2) == 0 ? -halfHeight : halfHeight);
        var diffX = cornerX - center.X;
        var diffY = cornerY - center.Y;
        bound = MathF.Max(bound, MathF.Sqrt(diffX * diffX + diffY * diffY));
    }
}
```
