    // Idle，不再触发归属变更与特效
    ref var state = ref celestialBody.Get<ColonizationState>();
    if (
        state.Team != conversionTeam
        || state.Progress != colonizable.Volume
        || state.Event != ColonizationEvent.Idle
    )
