#!/usr/bin/perl
use strict;
use warnings;
use utf8;
binmode(STDOUT, ":encoding(UTF-8)");

my $out = "/tmp/opencode/csharpier_boundary_test.cs";

sub width {
    my ($s) = @_;
    my $w = 0;
    for my $c (split //, $s) { $w += (ord($c) > 0x2E7F) ? 2 : 1; }
    return $w;
}

open(my $fh, ">:encoding(UTF-8)", $out) or die $!;
print $fh "class CSharpierWidthBoundaryTest\n{\n";

# ASCII 家族：属性与普通调用，宽度 96..104
for my $w (96 .. 104) {
    # 属性行：固定部分 47 列（缩进 4 + [FineWith(typeof(Sys), " ... ", typeof(Sprite))]）
    my $pad_a = "a" x ($w - 47);
    my $line_a = "    [FineWith(typeof(Sys), \"$pad_a\", typeof(Sprite))]";
    die "attr width mismatch" unless width($line_a) == $w;
    print $fh "    // MARK attr-ascii-$w\n$line_a\n    void AttrAscii$w() { }\n\n";

    # 普通调用行：固定部分 51 列（缩进 8）
    my $pad_c = "c" x ($w - 51);
    my $line_c = "        Call(typeof(Sys), \"$pad_c\", typeof(Sprite));";
    die "call width mismatch" unless width($line_c) == $w;
    print $fh "    // MARK call-ascii-$w\n    void CallAscii$w()\n    {\n$line_c\n    }\n\n";
}

# CJK 家族：命中 98..101 列（汉字按 2 列计）
for my $w (98 .. 101) {
    my $fill = $w - 47;             # 理由字符串显示宽度
    my $cjk  = int($fill / 2);      # 汉字个数（每个 2 列）
    my $rest = $fill - $cjk * 2;    # 余下用 ASCII 填充
    my $reason = ("汉" x $cjk) . ("z" x $rest);
    my $line = "    [FineWith(typeof(Sys), \"$reason\", typeof(Sprite))]";
    die "cjk width mismatch: got " . width($line) . " want $w" unless width($line) == $w;
    print $fh "    // MARK attr-cjk-$w\n$line\n    void AttrCjk$w() { }\n\n";
}

print $fh "}\n";
close($fh);
print "generated $out\n";

