    /// </summary>
    public Entity ConversionTeam;

    /// <summary>
    /// 半径的扩张速度
    /// </summary>
    public float ConversionSpeed;

    /// <summary>
    /// 表现扩张范围的视觉子实体
    /// </summary>
    public Entity Visual;
}

using OpenSolarMax.Game.Modding.ECS;

namespace OpenSolarMax.Mods.S2.Components;

/// <summary>
/// 转化波的状态：当前半径
/// </summary>
[Component]
public struct ConversionWaveState
{
    /// <summary>
    /// 当前半径
    /// </summary>
    public float Radius;
}

using Arch.Buffer;
using Arch.Core;
using Microsoft.Extensions.Configuration;
using Nine.Assets;
using OpenSolarMax.Game.Modding.Concept;
using OpenSolarMax.Game.Modding.Configuration;
using OpenSolarMax.Mods.S2.Components;

namespace OpenSolarMax.Mods.S2.Concepts;

public static partial class ConceptNames
{
    public const string ConvertingDilator = "ConvertingDilator";
}

/// <summary>
/// 转化 dilator 概念：在 dilator 的基础上，被占领时释放转化波，
/// 把沿途的天体与舰船转为指定阵营。白马非马，独立于 <see cref="ConceptNames.Dilator"/>
/// </summary>
[Define(ConceptNames.ConvertingDilator)]
public abstract class ConvertingDilatorDefinition : IDefinition
{
    public static Signature Signature { get; } =
        DilatorDefinition.Signature
        + new Signature(typeof(ConvertingDilatorConfig), typeof(ConvertingDilatorState));
}

[Describe(ConceptNames.ConvertingDilator)]
public class ConvertingDilatorDescription : DilatorDescription
{
    /// <summary>
    /// 转化波的目标阵营
    /// </summary>
    public Entity ConversionTeam { get; set; } = Entity.Null;

    /// <summary>
    /// 转化波半径的扩张速度
    /// </summary>
    public float ConversionSpeed { get; set; }
}

[Apply(ConceptNames.ConvertingDilator)]
public class ConvertingDilatorApplier(
    IAssetsManager assets,
    IConceptFactory factory,
    [Section("applier:celestial_body", "applier:dilator")] IConfiguration configs
) : IApplier<ConvertingDilatorDescription>
{
    private readonly DilatorApplier _dilatorApplier = new(assets, factory, configs);

    public void Apply(
        CommandBuffer commandBuffer,
        Entity entity,
        ConvertingDilatorDescription desc
    )
    {
        _dilatorApplier.Apply(commandBuffer, entity, desc);

        commandBuffer.Set(
            in entity,
            new ConvertingDilatorConfig
            {
                ConversionTeam = desc.ConversionTeam,
                ConversionSpeed = desc.ConversionSpeed,
            }
        );
    }
}

using Arch.Buffer;
using Arch.Core;
using Microsoft.Xna.Framework;
using Nine.Assets;
using Nine.Graphics;
using OpenSolarMax.Game.Modding.Concept;
using OpenSolarMax.Mods.Common.Components;
using OpenSolarMax.Mods.S2.Components;

namespace OpenSolarMax.Mods.S2.Concepts;

public static partial class ConceptNames
{
    public const string ConversionWave = "ConversionWave";
}

/// <summary>
/// 转化波概念：自 dilator 位置向外扩张，把沿途的天体与舰船转为目标阵营。
/// 仅在运行时由触发系统创建
/// </summary>
[Define(ConceptNames.ConversionWave)]
public abstract class ConversionWaveDefinition : IDefinition
{
    public static Signature Signature { get; } =
        TransformableDefinition.Signature
        + new Signature(typeof(ConversionWaveConfig), typeof(ConversionWaveState));
}

[Describe(ConceptNames.ConversionWave)]
public class ConversionWaveDescription : IDescription
{
    /// <summary>
    /// 转化波中心的位置
    /// </summary>
    public required Vector3 Position { get; set; }

    /// <summary>
    /// 转化波的目标阵营
    /// </summary>
    public Entity ConversionTeam { get; set; } = Entity.Null;

    /// <summary>
    /// 半径的扩张速度
    /// </summary>
    public float ConversionSpeed { get; set; }
}

[Apply(ConceptNames.ConversionWave)]
public class ConversionWaveApplier(IAssetsManager assets, IConceptFactory factory)
    : IApplier<ConversionWaveDescription>
{
    private readonly TextureRegion _haloTexture = assets.Load<TextureRegion>(
        Content.Textures.SolarMax2_Atlas_json + ":Halo"
    );

    private readonly TransformableApplier _transformableApplier = new(factory);

    public void Apply(CommandBuffer commandBuffer, Entity entity, ConversionWaveDescription desc)
    {
        var world = World.Worlds[entity.WorldId];

        _transformableApplier.Apply(
            commandBuffer,
            entity,
            new TransformableDescription
            {
                Transform = new AbsoluteTransformOptions { Translation = desc.Position },
            }
        );

        // 表现扩张范围的视觉子实体。尺寸不入动画曲线，由结算系统逐帧写为当前直径的两倍
        var visual = factory.Make(
            world,
            commandBuffer,
            new TeamInheritableDrawableDescription
            {
                Transform = new RelativeTransformOptions { Parent = entity },
                Texture = _haloTexture,
                Blend = SpriteBlend.Additive,
                Team = desc.ConversionTeam,
                VisualStyle = VisualStyle.Effect,
            }
        );

        commandBuffer.Set(
            in entity,
            new ConversionWaveConfig
            {
                ConversionTeam = desc.ConversionTeam,
                ConversionSpeed = desc.ConversionSpeed,
                Visual = visual,
            }
        );

        // 视觉子实体依赖转化波：转化波被销毁时视觉随之销毁
        factory.Make(
            world,
            commandBuffer,
            new DependenceDescription { Dependent = visual, Dependency = entity }
        );
    }
}

