119:         // 外循环：执行 LateUpdate1 系统并检查是否有延迟操作，有则经内循环一次性播放后继续循环
120:         for (var iteration = 0; ; iteration++)
121:         {
122:             // 如果迭代次数太多，则抛异常（上限 32 次系统执行）
123:             if (iteration >= MaxFixpointIterations)
124:                 throw new Exception(
125:                     $"fixpoint did not converge within {MaxFixpointIterations} iterations"
126:                 );
127: 
128:             Debug.Assert(_buffers[_currentIndex ^ 1].Size == 0);
