130:             // 执行 LateUpdate1 系统：声明延迟操作的系统把操作写入 CommandBuffer 缓存，其余直接执行
131:             foreach (var system in _lateUpdate1Systems)
132:             {
133:                 if (system is IDelayedCalcSystem delayedCalc)
134:                     delayedCalc.Update(CurrentCommandBuffer);
135:                 else if (system is ICalcSystem calc)
136:                     calc.Update();
