138: 
139:             // 若本轮没有任何系统缓存延迟操作，则不动点迭代收敛，退出循环
140:             if (_buffers[_currentIndex].Size == 0)
141:                 break;
142: 
143:             // 内循环：反复 Playback 直到 Buffered 排空（上限 32 次执行）
144:             for (var playbackIteration = 0; _buffers[_currentIndex].Size > 0; playbackIteration++)
145:             {
